import styled from '@emotion/styled';
import { Card } from 'components/UI';
import { theme } from 'theme';

type ItemMinWidth = '250' | '276' | '304' | '309' | '311' | '400';

interface StyledItemCardProps {
  $hide?: boolean;
  $cardBorder?: 'none';
  $minWidth?: ItemMinWidth;
}

export const StyledItemCard = styled(Card, {
  shouldForwardProp: (prop) =>
    !['$hide', '$cardBorder', '$minWidth'].includes(prop),
})<StyledItemCardProps>(({ $hide, $cardBorder, $minWidth }) => ({
  position: 'relative',
  borderRadius: theme.borderRadius['4'],
  minHeight: '56px',
  minWidth: '250px',
  maxWidth: '250px',
  flex: 1,
  border: '1px solid rgba(0, 0, 0, 0.1)',
  overflow: 'hidden',

  '&.expanded': {
    maxWidth: 'none',
  },

  ...($hide && { display: 'none' }),
  ...($cardBorder === 'none' && { border: 'none' }),
  ...($minWidth === '250' && { minWidth: '250px' }),
  ...($minWidth === '276' && { minWidth: '276px' }),
  ...($minWidth === '304' && { minWidth: '304px' }),
  ...($minWidth === '309' && { minWidth: '309px' }),
  ...($minWidth === '311' && { minWidth: '311px' }),
  ...($minWidth === '400' && { minWidth: '400px' }),
}));

interface StyledItemHeaderContainerProps {
  $isExpanded?: boolean;
  $borderBottom?: 'hidden';
}

export const StyledItemHeaderContainer =
  styled.div<StyledItemHeaderContainerProps>(
    ({ $isExpanded, $borderBottom }) => ({
      position: 'relative',
      display: 'flex',
      gap: theme.spacing['4'],
      padding: theme.spacing['4'],
      height: 'min-content',
      borderBottom: `1px solid ${theme.colors.charts.border.neutrals[20]}`,

      '&.paddingRight': {
        paddingRight: theme.spacing['8'],
      },

      ...($isExpanded && { alignItems: 'center' }),
      ...($borderBottom === 'hidden' && {
        borderBottom: '1px solid transparent',
      }),
    }),
  );

interface StyledItemButtomContainerProps {
  $isExpanded?: boolean;
}

export const StyledItemButtomContainer =
  styled.div<StyledItemButtomContainerProps>(({ $isExpanded }) => ({
    position: 'absolute',
    top: '16px',
    right: '16px',
    maxWidth: '40px',

    button: {
      maxWidth: '40px !important',
      minWidth: '40px !important',
    },

    ...($isExpanded && {
      top: '50%',
      transform: 'translateY(-50%)',
    }),
  }));
